import math
def control(obs):
    h = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {}) or {}
    left = right = None
    for name, side in [('left_mirror', 'left'), ('right_mirror', 'right')]:
        v = views.get(name) or {}
        vals = []
        for b, d in v.get('walls', []):
            if abs(b) >= 145:
                y = (1 if side == 'left' else -1) * d * math.sin(math.radians(b))
                if y > 0.1:
                    vals.append(y)
        if vals:
            if side == 'left': left = min(vals)
            else: right = min(vals)
    # Positive steering makes the trailer rear move right while reversing.
    correction = 0.0
    if left is not None and right is not None:
        correction = max(-6.0, min(6.0, 2.0 * (right - left)))
    steer = max(-10.0, min(10.0, 1.5 * h + correction))
    return (steer, -0.18, -64.0 if int(obs.get('t', 0) / 2) % 2 == 0 else 64.0)

