import math
phase='clear'
start_t=None
def control(obs):
    global phase,start_t
    t=obs.get('t',0.0)
    if start_t is None: start_t=t
    if phase=='clear':
        if t-start_t < 7.0 or obs.get('status')=='PINNED':
            return (12.0, 0.6, -41.0)
        phase='reverse'
    h=obs.get('hitch_deg',0.0)
    steer=max(-30.0,min(30.0,1.0*h))
    cam=obs.get('views',{}).get('camera') or {}
    walls=cam.get('walls',[])
    # Keep the trailer centered between nearby paired rails in camera view.
    pts=[]
    org=cam.get('origin',[0.0,0.0])
    for b,d in walls:
        a=math.radians(b)
        x=org[0]+d*math.cos(a); y=org[1]+d*math.sin(a)
        if x < -0.5 and abs(y)<8.0: pts.append((x,y))
    neg=[p for p in pts if p[1]<0]; pos=[p for p in pts if p[1]>0]
    if neg and pos:
        left=min(pos,key=lambda p:abs(p[0]+5.0)); right=min(neg,key=lambda p:abs(p[0]-left[0]))
        cy=(left[1]+right[1])/2.0
        steer += max(-8.0,min(8.0,-1.2*cy))
    return (max(-35.0,min(35.0,steer)),-0.45,-41.0)

