import math
def control(obs):
    h=obs.get('hitch_deg',0.0)
    cam=obs.get('views',{}).get('camera') or {}
    walls=cam.get('walls',[])
    org=cam.get('origin',[0.0,0.0])
    pts=[]
    for b,d in walls:
        a=math.radians(b)
        x=org[0]+d*math.cos(a); y=org[1]+d*math.sin(a)
        if x < -0.5 and d < 12: pts.append((x,y))
    left=[p for p in pts if p[1]>0.25]; right=[p for p in pts if p[1]<-0.25]
    corr=0.0
    if left and right:
        l=min(left,key=lambda p:abs(p[0]+3.0)); r=min(right,key=lambda p:abs(p[0]-l[0]))
        corr=max(-5.0,min(5.0,-0.8*(l[1]+r[1])*0.5))
    steer=max(-25.0,min(25.0,1.2*h+corr))
    return (steer,-0.30,-41.0)

